public interface ICancellationPolicy
{
    decimal CalculateRefund(Reservation reservation, DateTime cancelledAt);
}

public class StandardCancellationPolicy : ICancellationPolicy
{
    public decimal CalculateRefund(Reservation reservation, DateTime cancelledAt)
    {
        var hoursBefore = (reservation.CheckIn.ToDateTime(TimeOnly.MinValue) - cancelledAt).TotalHours;
        return hoursBefore >= 48 ? reservation.Total : reservation.Total * 0.5m;
    }
}

public class Waitlist
{
    private readonly Queue<(RoomType type, DateOnly from, DateOnly to, Guest guest)> _queue = new();

    public void Join(RoomType type, DateOnly from, DateOnly to, Guest guest)
    {
        _queue.Enqueue((type, from, to, guest));
    }

    public (Reservation reservation, Guest guest)? Promote(Room room, DateOnly from, DateOnly to)
    {
        if (_queue.TryPeek(out var next) && next.type == room.Type && next.from == from && next.to == to)
        {
            _queue.Dequeue();
            return (new Reservation(room, next.guest, from, to), next.guest);
        }
        return null;
    }
}
